/bin/zsh -lc "python3 -B - <<'PY'
import os, stat, hashlib, json
snapshot = {}
for directory, dirs, files in os.walk('.', followlinks=False):
    for name in dirs + files:
        p = os.path.join(directory, name)
        rel = os.path.relpath(p, '.')
        s = os.lstat(p)
        if stat.S_ISLNK(s.st_mode):
            snapshot[rel] = ['symlink', s.st_mode, os.readlink(p)]
        elif stat.S_ISREG(s.st_mode):
            with open(p, 'rb') as f:
                digest = hashlib.file_digest(f, 'sha256').hexdigest()
            snapshot[rel] = ['file', s.st_mode, s.st_mtime_ns, digest]
        elif stat.S_ISDIR(s.st_mode):
            snapshot[rel] = ['directory', s.st_mode]
        else:
            snapshot[rel] = ['special', s.st_mode]
print(json.dumps(snapshot, ensure_ascii=False))
